                                                                                                                                                                                                      
  CREATE TABLE "TENANT_ISSUE"                                                                                                                                                              
   (	"ISSUE_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                           
	"CREATION_DATE" DATE NOT NULL ENABLE,                                                                                                                                                                
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                           
	"UPDATE_DATE" DATE NOT NULL ENABLE,                                                                                                                                                                  
	"DEL_FLAG" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                         
	"SUBMIT_USER_ID" NUMBER(20,0),                                                                                                                                                                       
	"SUBMIT_SOURCE" NVARCHAR2(32),                                                                                                                                                                       
	"DESCRIPTION" VARCHAR2(2000) NOT NULL ENABLE,                                                                                                                                                        
	"IMAGES_URL" NVARCHAR2(2000),                                                                                                                                                                        
	"AFFECTED_RANGE" NVARCHAR2(128),                                                                                                                                                                     
	"CALL_RANGE" NVARCHAR2(128),                                                                                                                                                                         
	"IS_END" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                           
	"REMARK" NVARCHAR2(600),                                                                                                                                                                             
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                  
	"MAP_ID" NUMBER,                                                                                                                                                                                     
	"WORK_TYPE" NUMBER DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                        
	"GROUP_CHAT_ID" NVARCHAR2(100),                                                                                                                                                                      
	"GROUP_CHAT_QRCODE_LINK" NVARCHAR2(200),                                                                                                                                                             
	"IS_CREATE_GROUP_CHAT" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                             
	"OWNER_SYNC_USER_ID" NVARCHAR2(50),                                                                                                                                                                  
	"STATUS" NVARCHAR2(20) DEFAULT 'WAIT' NOT NULL ENABLE,                                                                                                                                               
	"END_TIME" DATE,                                                                                                                                                                                     
	"START_FOLLOW_TIME" DATE,                                                                                                                                                                            
	"EXT_ORG_ID" NUMBER(20,0),                                                                                                                                                                           
	"DAILY_SERIAL_NUMBER" NUMBER,                                                                                                                                                                        
	"FAULT_CODE" NVARCHAR2(60),                                                                                                                                                                          
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                        
	 PRIMARY KEY ("ISSUE_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                 
   ) ;                                                                                                                                                                                                

